mapper.select:
SELECT COUNT(*)
FROM CMM_CODE
WHERE COM_CD_ID = #{comCdId}

mapper.insert:
INSERT INTO CMM_CODE (
    COM_CD_ID          /* 공통코드아이디 */
  , COM_CD_NM          /* 공통코드명 */
  , COM_CD_EXPLN       /* 공통코드설명 */
  , LINK_COM_CD_ID1    /* 연결공통코드아이디1 */
  , LINK_COM_CD_ID2    /* 연결공통코드아이디2 */
  , USE_YN             /* 사용여부 */
  , SORT_SEQ           /* 정렬순서 */
  , REG_ID             /* 등록아이디 */
  , REG_DT             /* 등록일시 */
) VALUES (
    #{dto.comCdId}
  , #{dto.comCdNm}
  , #{dto.comCdExpln}
  , #{dto.linkComCdId1}
  , #{dto.linkComCdId2}
  , #{dto.useYn}
  , #{dto.sortSeq, jdbcType=NUMERIC}
  , #{regId}
  , SYSDATE
)

mapper.update:
UPDATE CMM_CODE
SET COM_CD_NM = #{dto.comCdNm}
  , COM_CD_EXPLN = #{dto.comCdExpln}
  , LINK_COM_CD_ID1 = #{dto.linkComCdId1}
  , LINK_COM_CD_ID2 = #{dto.linkComCdId2}
  , USE_YN = #{dto.useYn}
  , SORT_SEQ = #{dto.sortSeq, jdbcType=NUMERIC}
  , MOD_ID = #{modId}
  , MOD_DT = SYSDATE
WHERE COM_CD_ID = #{comCdId}

mapper.select:
SELECT COUNT(*)
FROM CMM_CODE_DTL
WHERE COM_CD_ID = #{comCdId}
  AND DTL_CD_ID = #{dtlCdId}

mapper.insert:
INSERT INTO CMM_CODE_DTL (
    COM_CD_ID          /* 공통코드아이디 */
  , DTL_CD_ID          /* 상세코드아이디 */
  , DTL_CD_NM          /* 상세코드명 */
  , DTL_CD_EXPLN       /* 상세코드설명 */
  , LNKG_DTL_CD_ID1    /* 연결상세코드아이디1 */
  , LNKG_DTL_CD_NM1    /* 연결상세코드명1 */
  , LNKG_DTL_CD_ID2    /* 연결상세코드아이디2 */
  , LNKG_DTL_CD_NM2    /* 연결상세코드명2 */
  , USE_YN             /* 사용여부 */
  , SORT_SEQ           /* 정렬순서 */
  , REG_ID             /* 등록아이디 */
  , REG_DT             /* 등록일시 */
) VALUES (
    #{comCdId}
  , #{dto.dtlCdId}
  , #{dto.dtlCdNm}
  , #{dto.dtlCdExpln}
  , #{dto.lnkgDtlCdId1}
  , #{dto.lnkgDtlCdNm1}
  , #{dto.lnkgDtlCdId2}
  , #{dto.lnkgDtlCdNm2}
  , #{dto.useYn}
  , #{dto.sortSeq, jdbcType=NUMERIC}
  , #{regId}
  , SYSDATE
)

mapper.update:
UPDATE CMM_CODE_DTL
SET DTL_CD_NM = #{dto.dtlCdNm}
  , DTL_CD_EXPLN = #{dto.dtlCdExpln}
  , LNKG_DTL_CD_ID1 = #{dto.lnkgDtlCdId1}
  , LNKG_DTL_CD_NM1 = #{dto.lnkgDtlCdNm1}
  , LNKG_DTL_CD_ID2 = #{dto.lnkgDtlCdId2}
  , LNKG_DTL_CD_NM2 = #{dto.lnkgDtlCdNm2}
  , USE_YN = #{dto.useYn}
  , SORT_SEQ = #{dto.sortSeq, jdbcType=NUMERIC}
  , MOD_ID = #{modId}
  , MOD_DT = SYSDATE
WHERE COM_CD_ID = #{comCdId}
  AND DTL_CD_ID = #{dtlCdId}

mapper.delete:
DELETE FROM CMM_CODE_DTL
WHERE COM_CD_ID = #{comCdId}
  AND DTL_CD_ID = #{dtlCdId}
